export const TIMED_REVISIONS = {"bank-easy-02":{"title":"QT-prolonging drugs","tiles":["Sotalol","Macrolides","Fluoroquinolones","Ondansetron"],"explanation":"Each prolongs the QT interval, mainly by blocking cardiac potassium channels, raising the risk of torsades de pointes.","tileExplanations":["A beta blocker with class III antiarrhythmic activity that blocks potassium channels and directly prolongs repolarization.","Macrolide antibiotics such as erythromycin and azithromycin block the delayed rectifier potassium current and prolong the QT interval.","Fluoroquinolones such as levofloxacin and moxifloxacin prolong the QT interval, especially with other risk factors.","A 5-HT3 antagonist antiemetic that causes dose-related QT prolongation, a standard warning especially with IV dosing."],"review":{"basis":"ai-revision-check","humanVerified":false}},"bank-easy-13":{"title":"Causes of acute pancreatitis","tiles":["Gallstones","Azathioprine","Hypertriglyceridemia","Hypercalcemia"],"explanation":"Each is an established cause of acute pancreatitis through acinar cell injury and premature activation of pancreatic enzymes.","tileExplanations":["The most common cause: a stone obstructing the ampulla triggers pancreatitis.","A thiopurine immunosuppressant that is a well-documented drug cause of acute pancreatitis, typically early in treatment.","Severe elevation (often above 1000 mg/dL) directly injures acinar cells.","Elevated calcium can activate trypsinogen prematurely within the pancreas."],"review":{"basis":"ai-revision-check","humanVerified":false}},"bank-easy-15":{"title":"Cyanotic congenital heart disease","tiles":["Tetralogy of Fallot","Transposition of the great arteries","Hypoplastic left heart syndrome","Pulmonary atresia"],"explanation":"Each lets deoxygenated blood reach the systemic circulation, through right-to-left shunting, mixing, or parallel circuits, causing cyanosis in the newborn period or early infancy.","tileExplanations":["Right-to-left shunting through a VSD, worsened by right ventricular outflow obstruction; the most common cyanotic lesion after infancy.","The aorta and pulmonary artery are switched, so the systemic and pulmonary circuits run in parallel; survival depends on mixing.","An underdeveloped left heart cannot support the systemic circulation, so systemic flow depends on the ductus, with obligatory mixing of pulmonary venous and systemic venous blood.","No outflow from the right ventricle to the pulmonary artery, so pulmonary blood flow depends on the ductus and systemic venous blood shunts right to left."],"review":{"basis":"ai-revision-check","humanVerified":false}},"bank-medium-03":{"title":"Gi-coupled receptors","tiles":["α2 receptor","M2 receptor","μ-opioid receptor","Somatostatin receptor"],"explanation":"Each couples to Gi, inhibiting adenylyl cyclase and lowering intracellular cAMP.","tileExplanations":["Presynaptic autoreceptor that inhibits further norepinephrine release via Gi.","Slows heart rate via Gi in the SA and AV nodes.","The main target of morphine and other opioids; couples to Gi/o to lower cAMP, open potassium channels, and reduce neurotransmitter release.","Broadly inhibits hormone release throughout the gut and endocrine system via Gi."],"review":{"basis":"ai-revision-check","humanVerified":false}},"bank-medium-04":{"title":"Structures traversing the cavernous sinus","tiles":["Internal carotid artery","CN III","CN V2","CN VI"],"explanation":"Each passes through the cavernous sinus, either in its lateral wall (CN III, IV, V1, V2) or through the sinus itself (internal carotid artery and CN VI).","tileExplanations":["Its cavernous segment runs through the body of the sinus, which is why a carotid-cavernous fistula causes a pulsatile, proptotic eye.","Runs in the lateral wall of the cavernous sinus, the most superior of the wall nerves.","The maxillary division of the trigeminal nerve runs in the lowest part of the lateral wall before exiting through the foramen rotundum.","Runs through the body of the sinus beside the internal carotid artery, making it the most vulnerable to compression."],"review":{"basis":"ai-revision-check","humanVerified":false}},"bank-medium-13":{"title":"Causes of eosinophilia","tiles":["Helminth infection","Asthma","Drug hypersensitivity reaction","Eosinophilic granulomatosis with polyangiitis"],"explanation":"Each is a classic cause of peripheral eosinophilia, spanning infectious, allergic, drug-related, and autoimmune causes.","tileExplanations":["Tissue-invasive worms such as Strongyloides and hookworm classically trigger a marked eosinophilic response.","Type 2 (allergic) airway inflammation drives eosinophil recruitment.","A hypersensitivity reaction to a drug can trigger eosinophilia, sometimes with rash and organ involvement (DRESS).","A small-vessel vasculitis with asthma, eosinophilia, and granulomatous inflammation."],"review":{"basis":"ai-revision-check","humanVerified":false}},"bank-hard-07":{"title":"___ phenomenon","tiles":["Raynaud","Koebner","Uhthoff","Somogyi"],"explanation":"Each eponym is conventionally followed by \"phenomenon,\" describing unrelated vascular, dermatologic, neurologic, or endocrine findings.","tileExplanations":["Raynaud phenomenon: episodic digital vasospasm triggered by cold or stress.","Koebner phenomenon: new skin lesions at sites of trauma, seen in psoriasis and lichen planus.","Uhthoff phenomenon: temporary worsening of neurologic symptoms, such as blurred vision, with heat or exercise in multiple sclerosis.","Somogyi phenomenon: rebound morning hyperglycemia after nocturnal hypoglycemia, a board classic even though CGM data suggest it is rare."],"review":{"basis":"ai-revision-check","humanVerified":false}},"bank-hard-11":{"title":"Star-related medical terminology","tiles":["Astrocytes","Starry-sky appearance","Stellate scar","Asteroid bodies"],"explanation":"Each term is named for a star or star shape (astro-, aster-, stellate, starry) and describes a completely different structure or finding.","tileExplanations":["Star-shaped glial cells of the CNS that support neurons and form glial scars; they stain for GFAP.","Starry-sky appearance: pale tingible-body macrophages scattered among dark lymphoma cells, classic for Burkitt lymphoma.","A central star-shaped scar seen in focal nodular hyperplasia (and fibrolamellar HCC) of the liver and radial scars of the breast.","Star-shaped inclusions within multinucleated giant cells of granulomas, classically described in sarcoidosis."],"review":{"basis":"ai-revision-check","humanVerified":false}},"bank-expert-03":{"title":"Exogenous hormone that suppresses its own upstream signal","tiles":["Glucocorticoid therapy","Levothyroxine overreplacement","Anabolic steroid use","Estrogen-containing oral contraceptives"],"explanation":"Each supplies an end-organ hormone (or its analog) from outside the body, which suppresses the hypothalamic or pituitary signal that would normally drive its own production.","tileExplanations":["Long-term exogenous glucocorticoids suppress CRH and ACTH, causing adrenal atrophy and risking adrenal insufficiency on withdrawal.","Excess thyroid hormone suppresses TSH, the classic cause of a low TSH with a normal gland.","Exogenous testosterone suppresses GnRH-driven LH and FSH, shutting down endogenous testosterone and sperm production.","Exogenous estrogen (with progestin) suppresses GnRH-driven FSH and LH, the basis of hormonal contraception."],"review":{"basis":"ai-revision-check","humanVerified":false}},"bank-expert-05":{"title":"Hormone runs high because the target tissue is resistant","tiles":["Laron syndrome","Pseudohypoparathyroidism","Androgen insensitivity syndrome","Nephrogenic diabetes insipidus"],"explanation":"In each, a hormone level is high not from a primary oversecreting gland but because its target tissue fails to respond, so feedback keeps pushing secretion up.","tileExplanations":["A defective GH receptor causes short stature with high GH but low IGF-1.","End-organ (renal) resistance to PTH keeps PTH high despite low calcium.","Defective androgen receptors blunt feedback, so LH and testosterone run high despite a female phenotype.","The kidney does not respond to ADH, so ADH levels rise as the body tries and fails to concentrate urine."],"review":{"basis":"ai-revision-check","humanVerified":false}},"bank-migrated-sys-mixed-0003-L1":{"title":"Cyanotic congenital heart defects","tiles":["Tetralogy of Fallot","Transposition of the great arteries","Hypoplastic left heart syndrome","Pulmonary atresia"],"explanation":"Each lets deoxygenated blood reach the systemic circulation, through right-to-left shunting, mixing, or parallel circuits, causing cyanosis.","tileExplanations":["The most common cyanotic defect after infancy: right-to-left flow across a VSD due to right ventricular outflow obstruction.","The aorta and pulmonary artery are swapped, creating two parallel circuits that depend on mixing.","An underdeveloped left heart cannot support the systemic circulation, so systemic flow depends on the ductus, with obligatory mixing of oxygenated and deoxygenated blood.","The pulmonary valve is atretic (closed), so pulmonary blood flow depends on the ductus and systemic venous blood shunts right to left."],"review":{"basis":"ai-revision-check","humanVerified":false}},"bank-migrated-sys-pulm-0002-L2":{"title":"Causes of an exudative pleural effusion","tiles":["Parapneumonic effusion","Malignancy","Acute pancreatitis","Tuberculosis"],"explanation":"Each inflames or invades the pleura, increasing capillary permeability and producing a protein-rich exudate.","tileExplanations":["Adjacent lung infection inflames the pleura, leaking protein-rich fluid.","Tumor invasion of the pleura and blocked lymphatic drainage produce an exudate.","Enzyme-rich inflammation crosses the diaphragm, causing a usually left-sided exudate with high pleural fluid amylase.","Pleural infection provokes an exudative, lymphocyte-rich effusion with high adenosine deaminase."],"review":{"basis":"ai-revision-check","humanVerified":false}},"bank-migrated-sys-renal-0001-L1":{"title":"Causes of anion gap metabolic acidosis","tiles":["Methanol","Diabetic ketoacidosis","Uremia","Cyanide poisoning"],"explanation":"Each generates an unmeasured acid that consumes bicarbonate, widening the anion gap.","tileExplanations":["Metabolized to formic acid, an unmeasured acid.","Ketoacids accumulate as unmeasured acids.","Retained organic acids, sulfates, and phosphates widen the gap in renal failure.","Blocks cytochrome c oxidase in the electron transport chain, forcing anaerobic metabolism and causing a high anion gap lactic acidosis."],"review":{"basis":"ai-revision-check","humanVerified":false}},"bank-migrated-sys-renal-0002-L4":{"title":"Classic glomerular biopsy patterns","tiles":["Linear IgG deposition","'Spike and dome' pattern","Mesangial IgA deposits","'Tram-track' basement membrane"],"explanation":"Each is a signature renal biopsy finding (on immunofluorescence, light, or electron microscopy) that points to a specific glomerular disease.","tileExplanations":["Antibodies bind uniformly along the glomerular basement membrane in anti-GBM (Goodpasture) disease.","Subepithelial immune deposits with basement membrane spikes create this appearance in membranous nephropathy.","IgA deposits in the mesangium define IgA nephropathy (Berger disease), also seen in IgA vasculitis.","GBM splitting from mesangial interposition and subendothelial deposits in membranoproliferative GN."],"review":{"basis":"ai-revision-check","humanVerified":false}},"bank-migrated-sys-renal-0003-L2":{"title":"Causes of hypokalemia","tiles":["Loop or thiazide diuretics","Hypomagnesemia","Albuterol","Insulin therapy"],"explanation":"Each lowers serum potassium, either by increasing renal potassium loss or by shifting potassium into cells.","tileExplanations":["Increased distal sodium delivery and secondary aldosterone drive renal potassium wasting.","Low intracellular magnesium removes the normal inhibition of ROMK channels, increasing renal potassium secretion; potassium stays low until magnesium is repleted.","A beta-2 agonist that stimulates the Na+/K+-ATPase and shifts potassium into cells.","Insulin stimulates the Na+/K+-ATPase and drives potassium into cells."],"review":{"basis":"ai-revision-check","humanVerified":false}},"bank-migrated-sys-renal-0003-L4":{"title":"Central diabetes insipidus vs SIADH","tiles":["Dilute urine despite high serum osmolality","Concentrated urine despite low serum osmolality","Responds to desmopressin","Improves with free water restriction"],"explanation":"Central DI and SIADH are opposite disorders of ADH secretion, and each finding here maps to exactly one of them.","tileExplanations":["Deficient ADH secretion means the kidney cannot concentrate urine, which is central diabetes insipidus.","Excess ADH action inappropriately concentrates urine, which is SIADH.","Central DI improves because the missing ADH is being replaced.","Reducing water intake corrects the dilutional hyponatremia of SIADH."],"review":{"basis":"ai-revision-check","humanVerified":false}},"bank-migrated-sys-neuro-0001-L2":{"title":"Signs of an anterior cerebral artery stroke","tiles":["Contralateral leg weakness, face/arm-sparing","Urinary incontinence","Personality/behavioral changes","Abulia"],"explanation":"The ACA supplies the medial frontal and parietal cortex: the leg motor area and the frontal structures governing behavior, initiative, and continence.","tileExplanations":["The ACA supplies the medial motor cortex representing the leg.","Medial frontal lobe involvement disrupts cortical inhibition of the bladder.","Frontal lobe territory governs behavior and executive function.","Loss of will and spontaneity (slowed, reduced speech and action) from medial frontal and cingulate damage, a classic ACA finding."],"review":{"basis":"ai-revision-check","humanVerified":false}},"bank-migrated-sys-neuro-0001-L4":{"title":"Named brainstem syndromes","tiles":["Locked-in syndrome","Lateral medullary (Wallenberg) syndrome","Internuclear ophthalmoplegia","Lateral pontine syndrome"],"explanation":"Brainstem lesions produce very specific, often crossed findings, and the combination of cranial nerve and long-tract signs pinpoints the level of the lesion.","tileExplanations":["A ventral pontine (basilar artery) lesion spares consciousness but severs nearly all motor output except vertical gaze and blinking.","PICA territory: crossed pain and temperature loss, dysphagia, hoarseness, vertigo, ipsilateral Horner syndrome, and ataxia.","A lesion in the medial longitudinal fasciculus disconnects the two eyes' horizontal gaze coordination.","AICA territory: ipsilateral facial paralysis, hearing loss, vertigo, and ataxia with crossed sensory loss."],"review":{"basis":"ai-revision-check","humanVerified":false}},"bank-migrated-sys-neuro-0002-L2":{"title":"Causes of chorea","tiles":["Huntington disease","Acute rheumatic fever","Levodopa-induced dyskinesia","Systemic lupus erythematosus"],"explanation":"Each causes basal ganglia dysfunction (degenerative, autoimmune, or drug-induced) that produces involuntary, irregular, dance-like movements.","tileExplanations":["CAG repeat expansion causes striatal neurodegeneration and chorea.","Sydenham chorea, a major Jones criterion, results from post-streptococcal antibodies that cross-react with basal ganglia neurons.","Long-term dopaminergic therapy can itself produce chorea-like movements.","Antiphospholipid or other autoantibodies can affect the basal ganglia."],"review":{"basis":"ai-revision-check","humanVerified":false}},"bank-migrated-sys-pharm-0002-L2":{"title":"Alpha blockade: uses and effects","tiles":["Benign prostatic hyperplasia","Pheochromocytoma","Orthostatic hypotension","Reflex tachycardia"],"explanation":"Alpha-1 blockade relaxes smooth muscle in the vasculature and prostate, which gives its uses, but also removes vasoconstrictive tone, which gives its predictable side effects.","tileExplanations":["Relaxes prostatic and bladder neck smooth muscle, easing urinary flow.","Irreversible alpha blockade with phenoxybenzamine is given before surgery to prevent a hypertensive crisis from released catecholamines; a beta blocker is added only after alpha blockade.","Loss of vasoconstrictive tone on standing drops blood pressure.","Vasodilation triggers baroreceptor-mediated compensatory tachycardia."],"review":{"basis":"ai-revision-check","humanVerified":false}},"bank-ext-007":{"title":"Features of anaphylaxis","tiles":["Crampy abdominal pain","Bronchospasm","Hypotension","Angioedema"],"explanation":"Mast cell and basophil degranulation (classically IgE-mediated, type I) releases histamine and other mediators, producing these systemic findings.","tileExplanations":["Smooth muscle contraction in the gut causes crampy pain and vomiting; persistent GI symptoms are a diagnostic criterion.","Smooth muscle constriction of the airways causes wheezing.","Vasodilation and capillary leak drop blood pressure (distributive shock).","Deep dermal or mucosal swelling, dangerous when it involves the airway."],"review":{"basis":"ai-revision-check","humanVerified":false}},"bank-ext-008":{"title":"Features of osteoarthritis","tiles":["Heberden nodes","First CMC joint involvement","Subchondral sclerosis","Osteophytes"],"explanation":"Non-inflammatory cartilage degeneration produces these characteristic joint distributions and radiographic findings.","tileExplanations":["Bony enlargement of the distal interphalangeal joints.","Arthritis at the base of the thumb is a classic osteoarthritis site, whereas RA favors the MCP joints and wrist.","Dense, thickened bone beneath worn cartilage, a classic osteoarthritis radiographic sign.","Reactive bony outgrowths at joint margins."],"review":{"basis":"ai-revision-check","humanVerified":false}},"bank-ext-021":{"title":"Associations of obstructive sleep apnea","tiles":["Obesity","Systemic hypertension","Daytime somnolence","Atrial fibrillation"],"explanation":"Repetitive upper-airway collapse during sleep produces these clinical features and cardiovascular consequences.","tileExplanations":["The leading risk factor via airway soft-tissue loading.","Recurrent hypoxia and sympathetic surges drive resistant hypertension.","Fragmented sleep causes excessive daytime sleepiness.","Hypoxia, sympathetic surges, and atrial stretch from negative intrathoracic pressure promote atrial fibrillation."],"review":{"basis":"ai-revision-check","humanVerified":false}},"bank-ext-025":{"title":"Features of Cushing syndrome","tiles":["Osteoporosis","Central obesity","Purple abdominal striae","Proximal muscle weakness"],"explanation":"Chronic cortisol excess drives fat redistribution, protein catabolism, bone loss, and skin thinning.","tileExplanations":["Cortisol inhibits osteoblasts and intestinal calcium absorption, causing bone loss and fragility fractures.","Truncal fat deposition with thin extremities.","Thinned skin over stretched, catabolized tissue.","Cortisol-driven proteolysis weakens proximal muscles."],"review":{"basis":"ai-revision-check","humanVerified":false}},"bank-ext-027":{"title":"Causes of microcytic anemia","tiles":["Iron deficiency","Thalassemia","Anemia of chronic disease","Lead poisoning"],"explanation":"Each impairs hemoglobin production (heme or globin synthesis), producing small, low-MCV red cells.","tileExplanations":["Insufficient iron for heme synthesis; the most common cause.","Reduced globin chain synthesis.","Hepcidin-driven iron sequestration limits erythropoiesis (often normocytic, can be microcytic).","Lead inhibits ferrochelatase and ALA dehydratase, blocking heme synthesis; basophilic stippling is characteristic."],"review":{"basis":"ai-revision-check","humanVerified":false}},"bank-ext-037":{"title":"Conditions associated with berry aneurysms","tiles":["ADPKD","Ehlers-Danlos syndrome","Fibromuscular dysplasia","Coarctation of the aorta"],"explanation":"Each predisposes to saccular (berry) aneurysms of the circle of Willis and subarachnoid hemorrhage.","tileExplanations":["Autosomal dominant polycystic kidney disease is the classic association; high-risk patients are screened.","Especially the vascular type, where defective type III collagen weakens arterial walls.","A nonatherosclerotic arteriopathy (classically renal and carotid, string-of-beads) with a well-established higher rate of intracranial aneurysms.","Associated with berry aneurysms (and a bicuspid aortic valve)."],"review":{"basis":"ai-revision-check","humanVerified":false}},"bank-ext-084":{"title":"ANCA-associated vasculitides","tiles":["Granulomatosis with polyangiitis","Microscopic polyangiitis","Churg-Strauss syndrome","Pauci-immune crescentic glomerulonephritis"],"explanation":"Each is a small-vessel vasculitis classified with the ANCA-associated vasculitides, with little or no immune-complex deposition (pauci-immune).","tileExplanations":["c-ANCA/anti-PR3; upper airway, lung, and kidney involvement.","p-ANCA/anti-MPO; kidney and lung without granulomas.","The eponym for eosinophilic granulomatosis with polyangiitis: asthma, eosinophilia, and granulomas; p-ANCA is positive in only a minority.","Renal-limited ANCA vasculitis: glomerular crescents with few or no immune deposits."],"review":{"basis":"ai-revision-check","humanVerified":false}},"bank-ext-090":{"title":"Barrier methods of contraception","tiles":["Male condom","Contraceptive sponge","Diaphragm","Cervical cap"],"explanation":"Each physically blocks sperm from reaching the egg rather than acting hormonally, the defining feature of barrier contraception.","tileExplanations":["A sheath worn on the penis; also reduces STI transmission.","A spermicide-containing foam sponge placed against the cervix that blocks and inactivates sperm.","A dome placed over the cervix, used with spermicide.","A smaller cap fitted snugly over the cervix, used with spermicide."],"review":{"basis":"ai-revision-check","humanVerified":false}},"bank-ext-096":{"title":"Features of HELLP syndrome","tiles":["Microangiopathic hemolysis","Elevated transaminases","Thrombocytopenia","Right upper quadrant pain"],"explanation":"HELLP is a severe variant of preeclampsia defined by hemolysis, elevated liver enzymes, and low platelets, and RUQ pain reflects the hepatic involvement.","tileExplanations":["Red cells fragment in damaged small vessels: schistocytes, high LDH, low haptoglobin.","Hepatic involvement raises AST and ALT.","Platelet consumption produces a low platelet count.","Hepatic swelling or ischemia causes RUQ or epigastric pain."],"review":{"basis":"ai-revision-check","humanVerified":false}},"bank-ext-101":{"title":"Psychiatric drugs needing drug levels or blood counts","tiles":["Lithium","Valproate","Carbamazepine","Clozapine"],"explanation":"Each needs routine serum drug levels or blood count monitoring because of a narrow therapeutic window or a serious hematologic toxicity.","tileExplanations":["Narrow therapeutic index; monitor levels plus renal and thyroid function.","Monitor drug levels, liver enzymes, and platelets (also teratogenic).","Monitor levels and CBC (risk of agranulocytosis and aplastic anemia); induces its own metabolism.","Requires scheduled absolute neutrophil counts due to risk of agranulocytosis."],"review":{"basis":"ai-revision-check","humanVerified":false}},"bank-ext-112":{"title":"UV-associated skin cancers","tiles":["Basal cell carcinoma","Squamous cell carcinoma","Melanoma","Merkel cell carcinoma"],"explanation":"Each is a skin malignancy for which ultraviolet exposure is a major risk factor, ranging from the most common and indolent (BCC) to aggressive tumors (melanoma, Merkel cell).","tileExplanations":["Most common; pearly papule with rolled borders and telangiectasias; rarely metastasizes.","Ulcerated or scaly lesion that can arise from actinic keratosis; can metastasize.","Pigmented lesion (ABCDE); prognosis by Breslow depth; high metastatic potential.","Rare, aggressive neuroendocrine tumor linked to UV damage and Merkel cell polyomavirus."],"review":{"basis":"ai-revision-check","humanVerified":false}}}
